function x({registerIndicator:g,sourceValues:M,nulls:N}){g({id:"oa-stderr",name:"Standard Error of Regression (STDERR)",category:"Statistics",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:14,min:3,max:1e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"stderr",type:"line",title:"Stderr",style:{color:"#ffeb3b",lineWidth:2}}],calc(r,a){const b=Math.max(3,Math.min(1e3,Math.floor(Number(a.period)||14))),u=M(r,a.source??"close"),s=new Array(r.length);for(let e=0;e<r.length;e++)s[e]=Number.isFinite(u[e])?u[e]:0;const c=new Array(r.length).fill(NaN);for(let e=0;e<r.length;e++){const o=Math.min(e+1,b);if(o<3)continue;const d=e-o+1;let n=0,i=0,f=0,m=0;for(let t=0;t<o;t++){const l=s[d+t];n+=t,i+=l,f+=t*l,m+=t*t}const p=o*m-n*n;if(p===0){c[e]=0;continue}const y=(o*f-n*i)/p,k=(i-y*n)/o;let h=0;for(let t=0;t<o;t++){const l=s[d+t]-(k+y*t);h+=l*l}const S=h/(o-2);c[e]=S>0?Math.sqrt(S):0}return{stderr:N(c)}}})}export{x as default};
